#include "matrix_pro/matrix_pro.hpp"

using matrix_pro::Matrix;

int main() {
    std::size_t n = 512;
    Matrix R = Matrix::randn(n, n);
    // Simetrik pozitif tanimli, iyi kosullu bir A uret
    Matrix A = add(elementwise_multiply(R, R), Matrix::identity(n));
    Matrix b = Matrix::ones(n, 1);

    float cond = condition_number(A);
    Matrix x = solve(A, b);                  // getrf + getrs

    // Artik normu: cozum ne kadar dogru?
    float residual = l2_norm(subtract(multiply(A, x), b));
    std::cout << "cond " << cond << " residual " << residual << '\n';

    float det = determinant(A);
    Matrix inv = inverse(A);
    return 0;
}

#include "matrix_pro/matrix_pro.hpp"

using matrix_pro::Matrix;

int main() {
    // Simetrik bir matris uret: A = R^T R (her zaman yari-pozitif tanimli)
    Matrix R = Matrix::randn(64, 64);
    Matrix A = multiply(transpose(R), R);

    EigenResult e = eigen(A);

    Matrix D = e.eigenvalues;      // artan sirada diyagonal
    Matrix V = e.eigenvectors;     // her kolon bir ozvektor

    // Yeniden kurma testi: A ~= V D V^T
    Matrix recon = multiply(multiply(V, D), transpose(V));
    std::cout << "reconstruction error: "
              << frobenius_norm(subtract(A, recon)) << '\n';

    // Toplam varyans = iz
    std::cout << "trace " << trace(A) << '\n';
    return 0;
}

#include "matrix_pro/matrix_pro.hpp"

using matrix_pro::Matrix;

int main() {
    Matrix A = Matrix::randn(512, 256);
    SVDResult d = svd(A);

    // Ilk k tekil ucluyu tut -> en iyi rank-k yaklasim
    std::size_t k = 32;
    Matrix Uk = slice(d.u, 0, A.rows(), 0, k);
    Matrix Sk = slice(d.s, 0, k, 0, k);
    Matrix Vk = slice(d.v, 0, A.cols(), 0, k);

    Matrix Ak = multiply(multiply(Uk, Sk), transpose(Vk));

    std::cout << "storage " << (512 * 256) << " -> "
              << (512 * k + k * k + 256 * k) << '\n';
    std::cout << "error " << frobenius_norm(subtract(A, Ak)) << '\n';

    std::cout << "rank " << rank(A) << '\n';
    return 0;
}

#include "matrix_pro/matrix_pro.hpp"

using matrix_pro::Matrix;

int main() {
    // Asiri-belirlenmis sistem: 500 denklem, 20 bilinmeyen
    Matrix A = Matrix::randn(500, 20);
    Matrix b = Matrix::randn(500, 1);

    // 1) Guvenli yol: SVD tabanli en kucuk kareler
    Matrix x1 = solve_least_squares(A, b);

    // 2) QR ile normal denklemden kacinma
    QRResult q = qr(A);
    Matrix y = solve(q.r, multiply(transpose(q.q), b));   // R ust ucgen

    std::cout << "residual (svd): "
              << l2_norm(subtract(multiply(A, x1), b)) << '\n';
    std::cout << "residual (qr) : "
              << l2_norm(subtract(multiply(A, y), b)) << '\n';
    return 0;
}
